```
import xml.etree.ElementTree as ET

def dict_to_xml(d):
   root = ET.Element('root')
   for k, v in d.items():
       e = ET.SubElement(root, k)
       e.text = str(v)
   return ET.tostring(root, encoding='unicode', method='xml')
